    "C132", "C138", "C122", "C111"
  ],
  "claims": [
    {
      "claim": "Human absolute oral bioavailability in the closest transferable contexts is above the 20% threshold: posaconazole 42–56% fasted and 85–87% fed (tablet), UDCA 78–87%, atazanavir >90% with food, and KNI-272 36.4% as a post-prandial capsule.",
      "card_ids": ["C03", "C04", "C10", "C14", "C20", "C12", "C23", "C06", "C54", "C57"]
    },
    {
      "claim": "L3 human oral-exposure records for structurally related HIV maturation inhibitors (GSK2838232, GSK3640254) show substantial plasma AUC/Cmax after oral dosing, supporting that large triterpenoid acid/amine scaffolds can be orally absorbed.",
      "card_ids": ["C103", "C105", "C74", "C87", "C96", "C95", "C89", "C75"]
    },
    {
      "claim": "L4 Caco-2 data for the triterpenoid acid asiatic acid show high apical-to-basolateral permeability (about 2–5 ×10−5 cm/s) with modest efflux ratios, supporting intestinal absorption potential for the triterpenoid core.",
      "card_ids": ["C132", "C138", "C122", "C111", "C155", "C118", "C130", "C144"]
    },
    {
      "claim": "L4 low water-solubility values for unmodified triterpenoid acids (oleanolic acid 4.65 µg/mL; KNI-727 5.5 µg/mL) are less transferable because the query contains ionizable basic amine and azole-pyridine groups absent in those records, and SNEDDS/surfactant data show formulation can overcome solubility; they are not affirmative evidence for F<20%.",
      "card_ids": ["C116", "C146", "C137", "C159", "C134"]
    },
    {
      "claim": "Rat perfusion for oleanolic acid shows low parent-blood P (3.0×10−6 cm/s) but high lumen disappearance (3.5×10−4 cm/s), indicating assay/metabolism context rather than a simple permeability barrier; low transferability to the query's modified scaffold.",
      "card_ids": ["C145", "C129"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": [
        "C116", "C132", "C138", "C122", "C111", "C145", "C129",
        "C110", "C137", "C159", "C134", "C146", "C140", "C143"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in any species.",
    "No query-specific solubility or permeability measurement; L4 records are for related triterpenoid acids lacking the query's basic amine/azole-pyridine modifications.",
    "Query formulation, prandial state, and dose are unspecified; food effects and formulation can be large for lipophilic triterpenoid acids.",
    "L3 GSK exposure records lack IV comparators and some were obtained with ritonavir boosting; unboosted F for the query is unknown.",
    "No query-specific first-pass, efflux, or intestinal metabolism data; L5 may address gut-wall effects.",
    "The low parent-blood P for oleanolic acid may reflect intestinal metabolism/sequestration; relevance to the query is uncertain."
  ],
  "decision_summary": "L4 is mixed: Caco-2 permeability for triterpenoid acids is supportive, while water solubility is low but formulation-dependent and less transferable because the query has ionizable amine/azole modifications. No affirmative F<20% evidence is added, so the high prediction is retained with moderate confidence."
}

